<template>
  <back-home-btn style="background: rgba(123, 123, 123, 0.8); height: 95vh">
    <template>
      <div class="flowCanvasNew">
        <div
          class="flowCanvasNew-public flowCanvasNew-top"
          v-if="roadType == '1'"
        >
          <!-- _1/左侧：上行 -->
          <div
            class="car"
            v-for="(item, index) in radarMessages"
            :key="`car${index}`"
            :style="{
              left: (item.y / 100) * baseProportion + 'px', // 根据实时的y坐标计算（1：100 * 基础比例）
              bottom:
                (item.x / 100) * baseProportion * magnification + 14 + 'px', // 根据实时的x坐标计算（1：100 * 基础比例）
            }"
          >
            <div class="car-title">{{ item.speed / 100 }} km/h</div>
            <!-- 区分大小车 -->
            <img
              :src="`/img/mqtt/${
                item.type == 2 ? 'small' : item.type == 3 ? 'big' : ''
              }_car.png`"
              alt=""
            />
            <!--            <img :src="`/img/mqtt/small_car.png`" alt="" />-->
          </div>
        </div>

        <div
          class="flowCanvasNew-public flowCanvasNew-bottom"
          v-if="roadType == '3'"
        >
          <!-- _3/右侧：下行 -->
          <div
            class="car"
            v-for="(item, index) in radarMessages"
            :key="`car${index}`"
            :style="{
              right: (item.y / 100) * baseProportion + 'px', // 根据实时的y坐标计算（1：100 * 基础比例）
              top: (item.x / 100) * baseProportion * magnification - 14 + 'px', // 根据实时的x坐标计算（1：100 * 基础比例）减去 车辆标题的高度
            }"
          >
            <div class="car-title">{{ item.speed / 100 }} km/h</div>
            <img
              class="car-transform"
              :src="`/img/mqtt/${
                item.type == 2 ? 'small' : item.type == 3 ? 'big' : ''
              }_car.png`"
              alt=""
            />
            <!--            <img :src="`/img/mqtt/small_car.png`" alt="" />-->
          </div>
        </div>

        <div class="flowCanvasNew-carId">{{ carId }}</div>

        <mqttComp
          ref="mqttComp"
          :topic="topic"
          :mqttUrl="mqttUrl"
          :mqttOpts="mqttOpts"
          @message-received="getMqttMessage"
          @mqtt-close="mqttClose"
        />
      </div>

      <el-button type="danger" @click="handleReceive(0)">停止接收</el-button>
      <el-button @click="handleReceive(1)">开始接收</el-button>
    </template>
  </back-home-btn>
</template>

<script>
import mqttComp from "@/components/mqttComp/mqttComp.vue";
import { demoData2 } from "/public/mqttDemoData";

export default {
  name: "flowCanvasNew",
  components: { mqttComp },
  watch: {
    devNum: {
      handler(newVal) {},
    },
  },
  data() {
    return {
      mqttUrl: {
        head: "ws",
        host: "49.233.4.226",
        port: 8083,
        tailPath: "mqtt",
      },
      mqttOpts: {
        keepalive: 60,
        clientId: "clientId-" + Math.random().toString(16).substr(2, 8),
        username: "client_qf",
        password: "qf@jpkj.2024",
        connectTimeout: 10 * 1000,
        path: "/mqtt",
      },
      baseProportion: 2.28, // 基础比例【684px / 300】
      magnification: 1.91, // 放大倍数 【车道宽度按照5m算应该为11.4px，但是背景图单车道为22px，即放大了1.93倍】
      radarMessages: [],
      // radarMessages: demoData2.data.filter((car) => this.makeCoordinateRule(car)),
      replayTimer: null,
      spuriousNum: 2, // 底部假的路段数量
      carId: [],
      /* 一下三个数据动态修改，demo这里是固定了做演示 */
      devNum: "g335k76_195_3", // 雷达编号 g335k76_195_1
      topic: `smart_trans/g335k76_195_3/up/track`, // 订阅主题 smart_trans/${devNum}/up/track
      roadType: 3, // _1/左侧：上行、_3/右侧：下行 // this.devNum?.slice(-1) 截取devNum的最后一位
    };
  },
  methods: {
    makeCoordinateRule(car) {
      // 1. 目标类型必须是2， 3
      // 2.车身width，Height 必须大于0
      // 3. id不为0
      // y 大于200 小于 28000
      // 目标所属车道 必须是11,12,13...
      let laneNoArr = [
        11,
        12,
        13,
        // 14,
        // 15,
        "11",
        "12",
        "13",
        // "14",
        // "15",
        31,
        32,
        33,
        // 34,
        // 35,
        "31",
        "32",
        "33",
        // "34",
        // "35",
        // 255,
        // "255",
      ];
      return (
        [2, 3, "2", "3"].includes(car.type) &&
        car.width > 0 &&
        car.height > 0 &&
        car.y > 100 &&
        car.y < 28000 &&
        ![0, "0"].includes(car.id) &&
        laneNoArr.includes(car.laneNo)
      );
    },

    getMqttMessage(message) {
      console.log(message, "message");
      this.radarMessages = [];
      this.radarMessages =
        message?.data.filter((car) => this.makeCoordinateRule(car)) || [];
      if (this.radarMessages.length > 0) {
        this.carId = this.radarMessages.map((e) => e.id);
        // console.log("mqtt接收到的消息是:", this.radarMessages);
        this.radarMessages.forEach((item) => {
          console.log(
            `id：${item.id}，
            x：${item.x}，
            y：${item.y}，
            laneNo：${item.laneNo}，
            speed: ${item.speed / 100} km/h，
            length: ${this.radarMessages.length}，
            `
          );
        });
      } else {
        this.carId = [];
      }
    },

    mqttClose() {
      this.$refs.mqttComp.mqttPublish(`smart_trans/${this.devNum}/down/track`, {
        id: this.devNum,
        switch: "off",
      });
    },

    replayRadar() {
      this.replayTimer = setInterval(() => {
        this.mqttClose();
      }, 1000 * 25);
    },

    handleReceive(type) {
      clearInterval(this.replayTimer);
      if (type === 0) {
        this.mqttClose();
      } else if (type === 1) {
        this.$refs.mqttComp.mqttPublish(
          `smart_trans/${this.devNum}/down/track`,
          {
            id: this.devNum,
            switch: "on",
          }
        );
      }
    },
  },
  created() {},
  mounted() {
    console.log("roadType：", this.roadType);
    console.log("topic：", this.topic);
    console.log("devNum：", this.devNum);
    console.log("radarMessages：", this.radarMessages);
    this.replayRadar();
  },
  destroyed() {
    clearInterval(this.replayTimer);
    this.replayTimer = null;
  },
};
</script>
